};
const profil = annuaire[email_secretaire] || {
  organisation: 'Mon Organisation',
  email_validation: 'contact@transferai.ci',
  expediteur: nomSecretaire
};

const subjectMatch = subject.match(/^\[(.+?)\]\s*(.+?)\s*[—-]\s*(.+?)\s*<(.+?)>\s*$/);

const type_courrier = subjectMatch ? subjectMatch[1].trim() : 'Courrier officiel';
